88	/// A kind of item that can be completed.
89	#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
90	#[serde(rename_all = "kebab-case")]
91	pub enum CompletionKind {
92	    /// A syntactical structure.
93	    Syntax,
94	    /// A function.
95	    Func,
96	    /// A type.
97	    Type,
98	    /// A function parameter.
99	    Param,
100	    /// A constant.
101	    Constant,
102	    /// A file path.
103	    Path,
104	    /// A package.
105	    Package,
106	    /// A label.
107	    Label,
108	    /// A font family.
109	    Font,
110	    /// A symbol.
111	    Symbol(EcoString),
112	}
