586	/// Add completions for the values of a parameter.
587	fn param_value_completions(ctx: &mut CompletionContext, func: &Func, param: &ParamInfo) {
588	    if param.name() == Some("font") {
589	        ctx.font_completions();
590	    } else if let Some(extensions) = path_completion(func, param) {
591	        ctx.file_completions_with_extensions(extensions);
592	    } else if func.name() == Some("figure") && param.name() == Some("body") {
593	        ctx.snippet_completion("image", "image(\"${}\"),", "An image in a figure.");
594	        ctx.snippet_completion("table", "table(\n  ${}\n),", "A table in a figure.");
595	    }
596	
597	    if let ParamInfo::Native(param) = param {
598	        ctx.cast_completions(&param.input);
599	    }
600	}
