602	/// Returns which file extensions to complete for the given parameter if any.
603	fn path_completion(func: &Func, param: &ParamInfo) -> Option<&'static [&'static str]> {
604	    Some(match (func.name(), param.name().unwrap_or_default()) {
605	        (Some("image"), "source") => {
606	            &["png", "jpg", "jpeg", "gif", "svg", "svgz", "webp", "pdf"]
607	        }
608	        (Some("csv"), "source") => &["csv"],
609	        (Some("plugin"), "source") => &["wasm"],
610	        (Some("cbor"), "source") => &["cbor"],
611	        (Some("json"), "source") => &["json"],
612	        (Some("toml"), "source") => &["toml"],
613	        (Some("xml"), "source") => &["xml"],
614	        (Some("yaml"), "source") => &["yml", "yaml"],
615	        (Some("bibliography"), "sources") => &["bib", "yml", "yaml"],
616	        (Some("bibliography"), "style") => &["csl"],
617	        (Some("cite"), "style") => &["csl"],
618	        (Some("raw"), "syntaxes") => &["sublime-syntax"],
619	        (Some("raw"), "theme") => &["tmtheme"],
620	        (_, "path") => &[],
621	        _ => return None,
622	    })
623	}
624	
625	/// Complete in markup mode.
626	fn complete_markup(ctx: &mut CompletionContext) -> bool {
627	    debug_assert_eq!(ctx.leaf.mode_after(), Some(SyntaxMode::Markup));
628	
629	    // Start of a reference: "@|".
630	    if ctx.leaf.kind() == SyntaxKind::Text && ctx.before.ends_with("@") {
631	        ctx.from = ctx.cursor;
632	        ctx.label_completions();
633	        return true;
634	    }
635	
636	    // An existing reference: "@he|".
637	    if ctx.leaf.kind() == SyntaxKind::RefMarker {
638	        ctx.from = ctx.leaf.offset() + 1;
639	        ctx.label_completions();
640	        return true;
641	    }
642	
643	    // Behind a half-completed binding: "#let x = |".
644	    if let Some(prev) = ctx.leaf.prev_leaf()
645	        && prev.kind() == SyntaxKind::Eq
646	        && prev.parent_kind() == Some(SyntaxKind::LetBinding)
647	    {
648	        ctx.from = ctx.cursor;
649	        code_completions(ctx, false);
650	        return true;
651	    }
652	
653	    // Behind a half-completed context block: "#context |".
654	    if let Some(prev) = ctx.leaf.prev_leaf()
655	        && prev.kind() == SyntaxKind::Context
656	    {
657	        ctx.from = ctx.cursor;
658	        code_completions(ctx, false);
659	        return true;
660	    }
661	
662	    // Directly after a raw block.
663	    let mut s = Scanner::new(ctx.text);
664	    s.jump(ctx.leaf.offset());
665	    if s.eat_if("```") {
666	        s.eat_while('`');
667	        let start = s.cursor();
668	        if s.eat_if(is_id_start) {
669	            s.eat_while(is_id_continue);
670	        }
671	        if s.cursor() == ctx.cursor {
672	            ctx.from = start;
673	            ctx.raw_completions();
674	        }
675	        return true;
676	    }
677	
678	    // Anywhere: "|".
679	    if ctx.explicit {
680	        ctx.from = ctx.cursor;
681	        markup_completions(ctx);
682	        return true;
683	    }
684	
685	    false
686	}
