833	/// Complete in code mode.
834	fn complete_code(ctx: &mut CompletionContext) -> bool {
835	    debug_assert_eq!(ctx.leaf.mode_after(), Some(SyntaxMode::Code));
836	
837	    // Start of embedded code in markup or math: "[#|]", "$#|$".
838	    // (if not in markup or math, the kind would be an `Error`).
839	    if ctx.leaf.kind() == SyntaxKind::Hash {
840	        ctx.from = ctx.cursor;
841	        code_completions(ctx, true);
842	        return true;
843	    }
844	
845	    // An existing identifier: "{ pa| }".
846	    // Ignores named pair keys as they are not variables (as in "(pa|: 23)").
847	    if ctx.leaf.kind() == SyntaxKind::Ident
848	        && (ctx.leaf.index() > 0 || ctx.leaf.parent_kind() != Some(SyntaxKind::Named))
849	    {
850	        ctx.from = ctx.leaf.offset();
851	        code_completions(ctx, false);
852	        return true;
853	    }
854	
855	    // Anywhere: "{ | }", "(|)", "(1,|)", "(a:|)".
856	    // But not within or after an expression, and also not part of a dictionary
857	    // key (as in "(pa: |,)")
858	    if ctx.explicit
859	        && ctx.leaf.parent_kind() != Some(SyntaxKind::Dict)
860	        && (ctx.leaf.kind().is_trivia()
861	            || matches!(
862	                ctx.leaf.kind(),
863	                SyntaxKind::LeftParen
864	                    | SyntaxKind::LeftBrace
865	                    | SyntaxKind::Comma
866	                    | SyntaxKind::Colon
867	            ))
868	    {
869	        ctx.from = ctx.cursor;
870	        code_completions(ctx, false);
871	        return true;
872	    }
873	
874	    false
875	}
