1050	/// Context for autocompletion.
1051	struct CompletionContext<'a> {
1052	    world: &'a (dyn IdeWorld + 'a),
1053	    output: Option<&'a dyn Output>,
1054	    text: &'a str,
1055	    before: &'a str,
1056	    after: &'a str,
1057	    leaf: &'a LinkedNode<'a>,
1058	    cursor: usize,
1059	    explicit: bool,
1060	    from: usize,
1061	    completions: Vec<Completion>,
1062	    seen_casts: FxHashSet<u128>,
1063	}
1064	
1065	impl<'a> CompletionContext<'a> {
1066	    /// Create a new autocompletion context.
1067	    fn new(
1068	        world: &'a (dyn IdeWorld + 'a),
1069	        output: Option<&'a dyn Output>,
1070	        source: &'a Source,
1071	        leaf: &'a LinkedNode<'a>,
1072	        cursor: usize,
1073	        explicit: bool,
1074	    ) -> Self {
1075	        let text = source.text();
1076	        Self {
1077	            world,
1078	            output,
1079	            text,
1080	            before: &text[..cursor],
1081	            after: &text[cursor..],
1082	            leaf,
1083	            cursor,
1084	            explicit,
1085	            from: cursor,
1086	            completions: vec![],
1087	            seen_casts: FxHashSet::default(),
1088	        }
1089	    }
1090	
1091	    /// A small window of context before the cursor.
1092	    fn before_window(&self, size: usize) -> &str {
1093	        Scanner::new(self.before).get(self.cursor.saturating_sub(size)..self.cursor)
1094	    }
