1096	    /// Add a prefix and suffix to all applications.
1097	    fn enrich(&mut self, prefix: &str, suffix: &str) {
1098	        for Completion { label, apply, .. } in &mut self.completions {
1099	            let current = apply.as_ref().unwrap_or(label);
1100	            *apply = Some(eco_format!("{prefix}{current}{suffix}"));
1101	        }
1102	    }
