1110	    ) {
1111	        self.completions.push(Completion {
1112	            kind: CompletionKind::Syntax,
1113	            label: label.into(),
1114	            apply: Some(snippet.into()),
1115	            detail: Some(docs.into()),
1116	        });
1117	    }
