1123	        for (family, iter) in book.families() {
1124	            let variants: Vec<_> = iter.filter_map(|id| book.info(id)).collect();
1125	            let is_math = variants.iter().any(|f| f.flags.contains(FontFlags::MATH));
1126	            let detail = summarize_font_family(variants);
