1155	    /// Add completions for all available files.
1156	    fn file_completions(&mut self, mut filter: impl FnMut(FileId) -> bool) {
1157	        let Some(current_id) = self.leaf.span().id() else { return };
1158	        let Some(current_dir) = current_id.vpath().parent() else { return };
1159	
