1335	    /// Add completions for a castable.
1336	    fn cast_completions(&mut self, cast: &CastInfo) {
1337	        // Prevent duplicate completions from appearing.
1338	        if !self.seen_casts.insert(typst::utils::hash128(cast)) {
1339	            return;
1340	        }
1341	
1342	        match cast {
1343	            CastInfo::Any => {}
1344	            CastInfo::Value(value, docs) => {
1345	                self.value_completion_full(None, value, false, None, Some(docs));
1346	            }
1347	            CastInfo::Type(ty) => {
1348	                if *ty == Type::of::<NoneValue>() {
1349	                    self.snippet_completion("none", "none", "Nothing.");
1350	                } else if *ty == Type::of::<AutoValue>() {
1351	                    self.snippet_completion("auto", "auto", "A smart default.");
1352	                } else if *ty == Type::of::<bool>() {
1353	                    self.snippet_completion("false", "false", "No / Disabled.");
1354	                    self.snippet_completion("true", "true", "Yes / Enabled.");
1355	                } else if *ty == Type::of::<Color>() {
1356	                    self.snippet_completion(
1357	                        "luma()",
1358	                        "luma(${v})",
1359	                        "A custom grayscale color.",
1360	                    );
1361	                    self.snippet_completion(
1362	                        "rgb()",
1363	                        "rgb(${r}, ${g}, ${b}, ${a})",
1364	                        "A custom RGBA color.",
1365	                    );
1366	                    self.snippet_completion(
1367	                        "cmyk()",
1368	                        "cmyk(${c}, ${m}, ${y}, ${k})",
1369	                        "A custom CMYK color.",
1370	                    );
1371	                    self.snippet_completion(
1372	                        "oklab()",
1373	                        "oklab(${l}, ${a}, ${b}, ${alpha})",
1374	                        "A custom Oklab color.",
1375	                    );
1376	                    self.snippet_completion(
1377	                        "oklch()",
1378	                        "oklch(${l}, ${chroma}, ${hue}, ${alpha})",
1379	                        "A custom Oklch color.",
1380	                    );
1381	                    self.snippet_completion(
1382	                        "color.linear-rgb()",
1383	                        "color.linear-rgb(${r}, ${g}, ${b}, ${a})",
1384	                        "A custom linear RGBA color.",
1385	                    );
1386	                    self.snippet_completion(
1387	                        "color.hsv()",
1388	                        "color.hsv(${h}, ${s}, ${v}, ${a})",
1389	                        "A custom HSVA color.",
1390	                    );
1391	                    self.snippet_completion(
1392	                        "color.hsl()",
1393	                        "color.hsl(${h}, ${s}, ${l}, ${a})",
1394	                        "A custom HSLA color.",
1395	                    );
1396	                    self.scope_completions(false, |value| value.ty() == *ty);
1397	                } else if *ty == Type::of::<Label>() {
1398	                    self.label_completions();
1399	                } else if *ty == Type::of::<Func>() {
1400	                    self.snippet_completion(
1401	                        "function",
1402	                        "(${params}) => ${output}",
1403	                        "A custom function.",
1404	                    );
1405	                } else {
1406	                    self.completions.push(Completion {
1407	                        kind: CompletionKind::Syntax,
1408	                        label: ty.long_name().into(),
1409	                        apply: Some(eco_format!("${{{ty}}}")),
1410	                        detail: Some(eco_format!("A value of type {ty}.")),
1411	                    });
1412	                    self.scope_completions(false, |value| value.ty() == *ty);
1413	                }
1414	            }
1415	            CastInfo::Union(union) => {
1416	                for info in union {
1417	                    self.cast_completions(info);
1418	                }
1419	            }
1420	        }
1421	    }
