1423	    /// Add completions for definitions that are available at the cursor.
1424	    ///
1425	    /// Filters the global/math scope with the given filter.
1426	    fn scope_completions(&mut self, parens: bool, filter: impl Fn(&Value) -> bool) {
1427	        // When any of the constituent parts of the value matches the filter,
1428	        // that's ok as well. For example, when autocompleting `#rect(fill: |)`,
1429	        // we propose colors, but also dictionaries and modules that contain
1430	        // colors.
1431	        let filter = |value: &Value| check_value_recursively(value, &filter);
1432	
1433	        let mut defined = BTreeMap::<EcoString, Option<Value>>::new();
1434	        named_items(self.world, self.leaf.clone(), |item| {
1435	            let name = item.name();
1436	            if !name.is_empty() && item.value().as_ref().is_none_or(filter) {
1437	                defined.insert(name.clone(), item.value());
1438	            }
1439	
1440	            None::<()>
1441	        });
1442	
1443	        for (name, value) in &defined {
1444	            if let Some(value) = value {
1445	                self.value_completion(name.clone(), value);
1446	            } else {
1447	                self.completions.push(Completion {
1448	                    kind: CompletionKind::Constant,
1449	                    label: name.clone(),
1450	                    apply: None,
1451	                    detail: None,
1452	                });
1453	            }
1454	        }
1455	
1456	        for (name, binding) in globals(self.world, self.leaf).iter() {
1457	            let value = binding.read();
1458	            if filter(value) && !defined.contains_key(name) {
1459	                self.value_completion_full(Some(name.clone()), value, parens, None, None);
1460	            }
1461	        }
1462	    }
1463	}
