1465	/// What kind of parentheses to autocomplete for a function.
1466	enum BracketMode {
1467	    /// Round parenthesis, with the cursor within: `(|)`.
1468	    RoundWithin,
1469	    /// Round parenthesis, with the cursor after them: `()|`.
1470	    RoundAfter,
1471	    /// Round parenthesis, with newlines and indent.
1472	    RoundNewline,
1473	    /// Square brackets, with the cursor within: `[|]`.
1474	    SquareWithin,
1475	}
1476	
1477	impl BracketMode {
1478	    fn of(func: &Func) -> Self {
1479	        // If we have no parameters or only the self one, it's friendlier to put
1480	        // the cursor after the method call.
1481	        if func.params().all(|param| param.name() == Some("self")) {
1482	            return Self::RoundAfter;
1483	        }
1484	
1485	        match func.name() {
1486	            Some(
1487	                "emph" | "footnote" | "quote" | "strong" | "highlight" | "overline"
1488	                | "underline" | "smallcaps" | "strike" | "sub" | "super",
1489	            ) => Self::SquareWithin,
1490	            Some("colbreak" | "parbreak" | "linebreak" | "pagebreak") => Self::RoundAfter,
1491	            Some("figure" | "table" | "grid" | "stack") => Self::RoundNewline,
1492	            _ => Self::RoundWithin,
1493	        }
1494	    }
1495	}
