    type Response = Option<(usize, Vec<Completion>)>;

    trait ResponseExt {
        fn completions(&self) -> &[Completion];
        fn labels(&self) -> BTreeSet<&str>;
        fn must_be_empty(&self) -> &Self;
        fn must_include<'a>(&self, includes: impl IntoIterator<Item = &'a str>) -> &Self;
        fn must_exclude<'a>(&self, excludes: impl IntoIterator<Item = &'a str>) -> &Self;
        fn at(&self, label: &str) -> &Completion;
    }

    impl ResponseExt for Response {
        fn completions(&self) -> &[Completion] {
            match self {
                Some((_, completions)) => completions.as_slice(),
                None => &[],
            }
        }

        fn labels(&self) -> BTreeSet<&str> {
            self.completions().iter().map(|c| c.label.as_str()).collect()
        }

        #[track_caller]
        fn must_be_empty(&self) -> &Self {
            let labels = self.labels();
            assert!(
                labels.is_empty(),
                "expected no suggestions (got {labels:?} instead)"
            );
            self
        }

        #[track_caller]
        fn must_include<'a>(&self, includes: impl IntoIterator<Item = &'a str>) -> &Self {
            let labels = self.labels();
            for item in includes {
                assert!(
                    labels.contains(item),
                    "{item:?} was not contained in {labels:?}",
                );
            }
            self
        }

        #[track_caller]
        fn must_exclude<'a>(&self, excludes: impl IntoIterator<Item = &'a str>) -> &Self {
            let labels = self.labels();
            for item in excludes {
                assert!(
                    !labels.contains(item),
                    "{item:?} was wrongly contained in {labels:?}",
                );
            }
            self
        }

        #[track_caller]
        fn at(&self, label: &str) -> &Completion {
            self.completions()
                .iter()
                .find(|c| c.label == label)
                .unwrap_or_else(|| panic!("found no completion for {label:?}"))
        }
    }

    trait CompletionExt {
        fn must_apply_as<'a>(&self, apply: impl Into<Option<&'a str>>) -> &Self;
        fn must_have_detail<'a>(&self, detail: impl Into<Option<&'a str>>) -> &Self;
    }

    impl CompletionExt for Completion {
        #[track_caller]
        fn must_apply_as<'a>(&self, apply: impl Into<Option<&'a str>>) -> &Self {
            assert_eq!(self.apply.as_deref(), apply.into());
            self
        }

        #[track_caller]
        fn must_have_detail<'a>(&self, detail: impl Into<Option<&'a str>>) -> &Self {
            assert_eq!(self.detail.as_deref(), detail.into());
            self
        }
    }

