        test("#{() .}", -2).must_include(["insert", "remove", "len", "all"]);
        test("$#() .$", -2).must_exclude(["insert", "remove", "len", "all"]);
        test("$std.array .$", -2).must_exclude(["insert", "remove", "len", "all"]);
        test("#() .a", -1).must_exclude(["insert", "remove", "len", "all"]);
