        test("$#col$", -2).must_include(["colbreak"]).must_exclude(["colon"]);
        test("$col$", -2).must_include(["colon"]).must_exclude(["colbreak"]);
        test("$(col)$", -3).must_include(["colon"]).must_exclude(["colbreak"]);
