17	/// A world for IDE testing.
18	#[derive(Clone)]
19	pub struct TestWorld {
20	    pub main: Source,
21	    files: Arc<TestFiles>,
22	    base: &'static TestBase,
23	}
24	
25	impl TestWorld {
26	    /// Create a new world for a single test.
27	    ///
28	    /// This is cheap because the shared base for all test runs is lazily
29	    /// initialized just once.
30	    pub fn new(text: &str) -> Self {
31	        let main = Source::new(Self::main_id(), text.into());
32	        Self {
33	            main,
34	            files: Arc::new(TestFiles::default()),
35	            base: singleton!(TestBase, TestBase::default()),
36	        }
37	    }
38	
39	    /// Add an additional source file to the test world.
40	    #[track_caller]
41	    pub fn with_source(mut self, path: &str, text: &str) -> Self {
42	        let id = RootedPath::new(VirtualRoot::Project, VirtualPath::new(path).unwrap())
43	            .intern();
44	        let source = Source::new(id, text.into());
45	        Arc::make_mut(&mut self.files).sources.insert(id, source);
46	        self
47	    }
48	
49	    /// Add an additional asset file to the test world.
50	    #[track_caller]
51	    pub fn with_asset(self, filename: &str) -> Self {
52	        self.with_asset_at(filename, filename)
53	    }
54	
55	    /// Add an additional asset file to the test world.
56	    #[track_caller]
57	    pub fn with_asset_at(mut self, path: &str, filename: &str) -> Self {
58	        let id = RootedPath::new(VirtualRoot::Project, VirtualPath::new(path).unwrap())
59	            .intern();
60	        let data = typst_dev_assets::get_by_name(filename).unwrap();
61	        let bytes = Bytes::new(data);
62	        Arc::make_mut(&mut self.files).assets.insert(id, bytes);
63	        self
64	    }
65	
66	    /// The ID of the main file in a `TestWorld`.
67	    pub fn main_id() -> FileId {
68	        *singleton!(
69	            FileId,
70	            RootedPath::new(VirtualRoot::Project, VirtualPath::new("main.typ").unwrap())
71	                .intern()
72	        )
73	    }
74	}
75	
76	impl World for TestWorld {
77	    fn library(&self) -> &LazyHash<Library> {
78	        &self.base.library
79	    }
80	
81	    fn book(&self) -> &LazyHash<FontBook> {
82	        &self.base.book
83	    }
84	
85	    fn main(&self) -> FileId {
86	        self.main.id()
87	    }
